mapper.select:
SELECT A.*,B.* FROM( SELECT tt1.rnum no, tt1.report_id, tt1.report_member_id, tt1.comment_id, tt1.reason, tt1.detail, tt1.status, tt1.processed_by_member_id, tt1.process_note, TO_CHAR(tt1.created_dt,'YYYY/MM/DD HH24:MI:SS') created_dt, TO_CHAR(tt1.processed_dt,'YYYY/MM/DD HH24:MI:SS') processed_dt, tt1.reporter_nickname, tt1.processor_nickname FROM( SELECT ROWNUM rnum, t1.* FROM ( SELECT rc.*, reporter.nickname reporter_nickname, processor.nickname processor_nickname FROM report_comment rc LEFT JOIN member reporter ON rc.report_member_id = reporter.member_id LEFT JOIN member processor ON rc.processed_by_member_id = processor.member_id
ORDER BY rc.created_dt DESC, rc.report_id DESC )t1 WHERE ROWNUM <= ( #{pageSize} * (#{pageNo} -1 ) + #{pageSize} ) )tt1 WHERE rnum >= ( #{pageSize} * (#{pageNo} -1 ) + 1 ) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM report_comment rc
) B
